/**
 * @fileoverview Input-blocking overlay utilities for automated browser control.
 *
 * While the browser agent performs an interactive operation, real user input
 * (clicks, keystrokes, scrolling) can race against the automation and corrupt
 * the page state. These helpers inject a full-viewport overlay that swallows
 * user input events and displays a notice that the browser is under agent
 * control.
 *
 * The overlay is suspended (pointer events disabled) around each automated
 * interactive tool call so the agent's own action reaches the page, then
 * resumed afterwards. It is always removed once the operation completes, even
 * if the operation fails.
 *
 * The script strings are passed to chrome-devtools-mcp's evaluate_script tool
 * which expects a plain function expression (NOT an IIFE).
 */

import type { BrowserManager } from './browserManager.js';
import { debugLogger } from '../../utils/debugLogger.js';

const INPUT_BLOCKER_ELEMENT_ID = '__gemini_input_blocker';

/**
 * Builds the JavaScript function string that injects the input-blocking
 * overlay.
 *
 * Returns a plain arrow-function expression (no trailing invocation) because
 * chrome-devtools-mcp's evaluate_script tool invokes it internally.
 */
function buildInjectionScript(): string {
  return `() => {
    const id = '${INPUT_BLOCKER_ELEMENT_ID}';
    const existing = document.getElementById(id);
    if (existing) existing.remove();

    const blocker = document.createElement('div');
    blocker.id = id;
    blocker.setAttribute('aria-hidden', 'true');
    blocker.setAttribute('role', 'presentation');

    Object.assign(blocker.style, {
      position: 'fixed',
      top: '0',
      left: '0',
      right: '0',
      bottom: '0',
      zIndex: '2147483646',
      pointerEvents: 'auto',
      cursor: 'not-allowed',
      background: 'transparent',
    });

    const label = document.createElement('div');
    label.textContent = 'Gemini CLI is controlling this browser';
    Object.assign(label.style, {
      position: 'fixed',
      top: '12px',
      left: '50%',
      transform: 'translateX(-50%)',
      padding: '6px 12px',
      background: 'rgba(66, 133, 244, 0.95)',
      color: '#ffffff',
      font: '13px sans-serif',
      borderRadius: '6px',
      pointerEvents: 'none',
    });
    blocker.appendChild(label);

    // Swallow user input events while the blocker is active so real user
    // interaction cannot race against the automated operation.
    const swallow = (e) => {
      e.stopPropagation();
      e.preventDefault();
    };
    [
      'click', 'dblclick', 'mousedown', 'mouseup', 'keydown', 'keyup',
      'keypress', 'wheel', 'touchstart', 'touchmove', 'contextmenu',
    ].forEach((type) => {
      blocker.addEventListener(type, swallow, true);
    });

    document.documentElement.appendChild(blocker);
    return 'input-blocker-injected';
  }`;
}

/**
 * Builds the JavaScript function string that removes the input-blocking
 * overlay.
 */
function buildRemovalScript(): string {
  return `() => {
    const el = document.getElementById('${INPUT_BLOCKER_ELEMENT_ID}');
    if (el) el.remove();
    return 'input-blocker-removed';
  }`;
}

/**
 * Builds the JavaScript function string that suspends the input-blocking
 * overlay by disabling its pointer-event capture. This lets the agent's own
 * automated action reach the underlying page element.
 */
function buildSuspendScript(): string {
  return `() => {
    const el = document.getElementById('${INPUT_BLOCKER_ELEMENT_ID}');
    if (el) el.style.pointerEvents = 'none';
    return 'input-blocker-suspended';
  }`;
}

/**
 * Builds the JavaScript function string that resumes the input-blocking
 * overlay by re-enabling its pointer-event capture.
 */
function buildResumeScript(): string {
  return `() => {
    const el = document.getElementById('${INPUT_BLOCKER_ELEMENT_ID}');
    if (el) el.style.pointerEvents = 'auto';
    return 'input-blocker-resumed';
  }`;
}

/**
 * Injects the input-blocking overlay into the current page.
 *
 * Errors from the underlying tool call are caught and swallowed so overlay
 * management never interrupts the agent's operation.
 */
export async function injectInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    debugLogger.log('Injecting input blocker...');

    const result = await browserManager.callTool(
      'evaluate_script',
      { function: buildInjectionScript() },
      signal,
    );

    if (result.isError) {
      debugLogger.warn('Failed to inject input blocker:', result);
    } else {
      debugLogger.log('Input blocker injected successfully');
    }
  } catch (error) {
    debugLogger.warn('Error injecting input blocker:', error);
    return undefined;
  }
}

/**
 * Removes the input-blocking overlay from the current page.
 *
 * Errors from the underlying tool call are caught and swallowed so removal
 * always resolves — the overlay should never outlive the operation.
 */
export async function removeInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    debugLogger.log('Removing input blocker...');

    const result = await browserManager.callTool(
      'evaluate_script',
      { function: buildRemovalScript() },
      signal,
    );

    if (result.isError) {
      debugLogger.warn('Failed to remove input blocker:', result);
    } else {
      debugLogger.log('Input blocker removed successfully');
    }
  } catch (error) {
    debugLogger.warn('Error removing input blocker:', error);
    return undefined;
  }
}

/**
 * Suspends the input blocker so an automated interactive action can reach the
 * page. Errors are caught and swallowed.
 */
export async function suspendInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    await browserManager.callTool(
      'evaluate_script',
      { function: buildSuspendScript() },
      signal,
    );
  } catch (error) {
    debugLogger.warn('Error suspending input blocker:', error);
    return undefined;
  }
}

/**
 * Resumes the input blocker after an automated interactive action completes.
 * Errors are caught and swallowed.
 */
export async function resumeInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    await browserManager.callTool(
      'evaluate_script',
      { function: buildResumeScript() },
      signal,
    );
  } catch (error) {
    debugLogger.warn('Error resuming input blocker:', error);
    return undefined;
  }
}
